from decimal import ROUND_HALF_EVEN, Context, Decimal, InvalidOperation

from .money import MAX_AMOUNT, format_amount, parse_amount

# Private context so summing never depends on or changes the global decimal context.
_SUM_CONTEXT = Context(prec=100, rounding=ROUND_HALF_EVEN, traps=[InvalidOperation])


def make_invoice(amounts):
    items = list(amounts)
    total = Decimal("0.00")
    for item in items:
        total = _SUM_CONTEXT.add(total, parse_amount(item))
    if total > MAX_AMOUNT:
        raise ValueError("total must be at most 1000000.00")
    return {"total": format_amount(total), "count": len(items)}
